use futures::Future;

/// Retry a fallible future up to `retries` additional times, waiting one
/// second between attempts. Returns the last error when every attempt fails.
pub async fn retry_future_n_times<T, E, Fut, F: FnMut() -> Fut>(
    mut f: F,
    retries: i32,
) -> Result<T, E>
where
    E: std::fmt::Display,
    Fut: Future<Output = Result<T, E>>,
{
    let mut count = 0;
    loop {
        match f().await {
            Ok(value) => break Ok(value),
            Err(err) if count >= retries => break Err(err),
            Err(err) => {
                count += 1;
                log::warn!("attempt {count} of {retries} failed, retrying in 1s: {err}");
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            }
        }
    }
}
